# Bootstrap Gitea admin + converge mirror repos
# Source: build.json .gitea.mirrors + secrets.yaml
# Run: after container is healthy (container-init calls this)
# Idempotent: safe to run multiple times
set -uo pipefail
API="http://localhost:3002/api/v1"
CONTAINER="gitea"

# Step 1: Create admin user (idempotent)
echo "-- Bootstrapping admin user --"
docker exec "$CONTAINER" gitea admin user create \
  --username "${GITEA_ADMIN_USER}" \
  --password "${GITEA_ADMIN_PASSWORD}" \
  --email "${GITEA_ADMIN_EMAIL}" \
  --admin \
  --must-change-password=false 2>&1 | grep -v "already exists" || true

# Step 2: Get or create API token
echo "-- Obtaining API token --"
TOKEN_FILE="/opt/containers/gitea/.gitea-token"
if [ -f "$TOKEN_FILE" ]; then
  TOKEN=$(cat "$TOKEN_FILE")
else
  TOKEN=$(curl -sf -X POST "$API/users/${GITEA_ADMIN_USER}/tokens" \
    -u "${GITEA_ADMIN_USER}:${GITEA_ADMIN_PASSWORD}" \
    -H "Content-Type: application/json" \
    -d '{"name":"init-mirrors","scopes":["all"]}' | jq -r '.sha1') || true
  if [ -n "$TOKEN" ] && [ "$TOKEN" != "null" ]; then
    echo "$TOKEN" > "$TOKEN_FILE"
    chmod 600 "$TOKEN_FILE"
    echo "  Token created and saved"
  else
    echo "  FAIL: could not create token"
    exit 1
  fi
fi

AUTH="-H \"Authorization: token $TOKEN\""
api() { eval curl -sf "$AUTH" -H "'Content-Type: application/json'" "$@"; }

# Step 3: Ensure org exists
echo "-- Converging Gitea mirrors --"
if ! api "$API/orgs/diego" >/dev/null 2>&1; then
  echo "Creating org: diego"
  api -X POST "$API/orgs" -d '{"username":"diego","visibility":"public"}' >/dev/null
fi

# Step 4: Ensure each mirror repo exists
if ! api "$API/repos/diego/cloud" >/dev/null 2>&1; then
  echo "Creating mirror: diego/cloud <- https://github.com/diegonmarcos/cloud.git"
  api -X POST "$API/repos/migrate" -d '{
    "clone_addr": "https://github.com/diegonmarcos/cloud.git",
    "repo_name": "cloud",
    "repo_owner": "diego",
    "mirror": true,
    "mirror_interval": "1h",
    "private": false,
    "service": "github"
  }' >/dev/null && echo "  OK cloud" || echo "  FAIL cloud"
else
  echo "EXISTS diego/cloud"
fi

if ! api "$API/repos/diego/cloud-data" >/dev/null 2>&1; then
  echo "Creating mirror: diego/cloud-data <- https://github.com/diegonmarcos/cloud-data.git"
  api -X POST "$API/repos/migrate" -d '{
    "clone_addr": "https://github.com/diegonmarcos/cloud-data.git",
    "repo_name": "cloud-data",
    "repo_owner": "diego",
    "mirror": true,
    "mirror_interval": "1h",
    "private": false,
    "service": "github"
  }' >/dev/null && echo "  OK cloud-data" || echo "  FAIL cloud-data"
else
  echo "EXISTS diego/cloud-data"
fi

if ! api "$API/repos/diego/front" >/dev/null 2>&1; then
  echo "Creating mirror: diego/front <- https://github.com/diegonmarcos/front.git"
  api -X POST "$API/repos/migrate" -d '{
    "clone_addr": "https://github.com/diegonmarcos/front.git",
