fi

if ! api "$API/repos/diego/front-data" >/dev/null 2>&1; then
  echo "Creating mirror: diego/front-data <- https://github.com/diegonmarcos/front-data.git"
  api -X POST "$API/repos/migrate" -d '{
    "clone_addr": "https://github.com/diegonmarcos/front-data.git",
    "repo_name": "front-data",
    "repo_owner": "diego",
    "mirror": true,
    "mirror_interval": "1h",
    "private": false,
    "service": "github"
  }' >/dev/null && echo "  OK front-data" || echo "  FAIL front-data"
else
