fi

if ! api "$API/repos/diego/unix" >/dev/null 2>&1; then
  echo "Creating mirror: diego/unix <- https://github.com/diegonmarcos/unix.git"
  api -X POST "$API/repos/migrate" -d '{
    "clone_addr": "https://github.com/diegonmarcos/unix.git",
